#include <Arduino.h>
#include <Servo.h>
#define DEBOUNCE_DELAY 150
#define STATE_DELAY 2000
Servo servo1, servo2;
const int btnPin = 2;  
const int servo1Pin = 3, servo2Pin = 4;  
const int leds[] = {5, 6, 7, 8, 9, 10, 11, 12, 13, 44};  
int state = 0;
unsigned long lastStateTime = 0;
bool btnActive = false;

void setup();
void loop();
void updateHardware(int s);
void setup() {
  servo1.attach(servo1Pin);
  servo2.attach(servo2Pin);
  pinMode(btnPin, INPUT_PULLUP);
  for (int i = 0; i < 10; i++) pinMode(leds[i], OUTPUT);
  updateHardware(0);  
}
void loop() {
  if (digitalRead(btnPin) == LOW && !btnActive && 
     (millis() - lastStateTime) > STATE_DELAY) {
    delay(DEBOUNCE_DELAY);
    if (digitalRead(btnPin) == LOW) {
      btnActive = true;
      state = (state + 1) % 3;
      updateHardware(state);
      lastStateTime = millis();
    }
  } 
  else if (digitalRead(btnPin) == HIGH) {
    btnActive = false;
  }
}
void updateHardware(int s) {
  switch(s) {
    case 0:  
      servo1.write(0);
      servo2.write(180);
      for (int i = 0; i < 10; i++) digitalWrite(leds[i], LOW);
      break;
    case 1:  
      servo1.write(90);
      servo2.write(90);
      for (int i = 0; i < 5; i++) digitalWrite(leds[i], HIGH);
      for (int i = 5; i < 10; i++) digitalWrite(leds[i], LOW);
      break;
    case 2:  
      servo1.write(180);
      servo2.write(0);
      for (int i = 0; i < 10; i++) digitalWrite(leds[i], HIGH);
      break;
  }
}
